-- A synthetic freight-network schema. Nothing in it is anyone's data: every
-- table, column and constraint here was written for this file.
--
-- It is a whole schema rather than a snippet because the defect it pins was
-- found by running the deployed service against a real customer schema and not
-- by a test, and no single statement in that schema broke any rule. Five of its
-- tables reference one table twice -- STATION_LINKS names STATIONS as both ends
-- of a link, and SHIPMENT_TRANSFERS, CONTAINER_MOVES, TARIFF_PAIRS and
-- ACCESS_TYPE_RULES do the same shape -- which is the ordinary way SQL models a
-- relationship between two rows of one table, and which used to come back as
-- ten false conflicts (two per pair: the columns and the constraint name) on a
-- job that could then never finish.
--
-- The counts the tests pin: 45 tables, 48 foreign keys, 5 parallel pairs. They
-- are the shape of the schema that met the defect, reproduced; the customer's
-- own file is not in this repository and never was needed to hold the shape.
CREATE TABLE APP_CONFIGURATION(
    ENTRY_KEY VARCHAR(64) NOT NULL,
    ENTRY_VALUE VARCHAR(255)
);
ALTER TABLE APP_CONFIGURATION ADD CONSTRAINT PK_APP_CONFIGURATION PRIMARY KEY(ENTRY_KEY);
CREATE TABLE PRINCIPALS(
    PRINCIPAL_NAME VARCHAR(64) NOT NULL,
    DISPLAY_NAME VARCHAR(64) NOT NULL,
    ENABLED BOOLEAN DEFAULT TRUE NOT NULL
);
ALTER TABLE PRINCIPALS ADD CONSTRAINT PK_PRINCIPALS PRIMARY KEY(PRINCIPAL_NAME);
CREATE TABLE PRINCIPAL_ROLES(
    ID BIGINT NOT NULL,
    NAME VARCHAR(64) NOT NULL,
    PRINCIPAL_NAME VARCHAR(64) NOT NULL
);
ALTER TABLE PRINCIPAL_ROLES ADD CONSTRAINT PK_PRINCIPAL_ROLES PRIMARY KEY(ID);
CREATE TABLE ACCESS_TYPES(
    TYPE_NAME VARCHAR(64) NOT NULL,
    TYPE_VALUE INTEGER NOT NULL
);
ALTER TABLE ACCESS_TYPES ADD CONSTRAINT PK_ACCESS_TYPES PRIMARY KEY(TYPE_NAME);
