ALTER TABLE CONTAINER_MOVES ADD CONSTRAINT FK_CM_CONTAINERS_SRC FOREIGN KEY(CONTAINER_REF_SRC) REFERENCES CONTAINERS(CONTAINER_REF);
ALTER TABLE CONTAINER_MOVES ADD CONSTRAINT FK_CM_CONTAINERS_DST FOREIGN KEY(CONTAINER_REF_DST) REFERENCES CONTAINERS(CONTAINER_REF);
ALTER TABLE TARIFF_PAIRS ADD CONSTRAINT FK_TP_TARIFFS_A FOREIGN KEY(TARIFF_CODE_A) REFERENCES TARIFFS(TARIFF_CODE);
ALTER TABLE TARIFF_PAIRS ADD CONSTRAINT FK_TP_TARIFFS_B FOREIGN KEY(TARIFF_CODE_B) REFERENCES TARIFFS(TARIFF_CODE);
ALTER TABLE ACCESS_TYPE_RULES ADD CONSTRAINT FK_ATR_TYPES_DOMAIN FOREIGN KEY(DOMAIN_NAME) REFERENCES ACCESS_TYPES(TYPE_NAME);
ALTER TABLE ACCESS_TYPE_RULES ADD CONSTRAINT FK_ATR_TYPES_TARGET FOREIGN KEY(TARGET_NAME) REFERENCES ACCESS_TYPES(TYPE_NAME);
ALTER TABLE PRINCIPAL_ROLES ADD CONSTRAINT FK_PR_PRINCIPALS FOREIGN KEY(PRINCIPAL_NAME) REFERENCES PRINCIPALS(PRINCIPAL_NAME);
ALTER TABLE OBJECT_PROTECTION ADD CONSTRAINT FK_OP_TYPES FOREIGN KEY(TYPE_NAME) REFERENCES ACCESS_TYPES(TYPE_NAME);
ALTER TABLE ACL_ENTRIES ADD CONSTRAINT FK_ACL_OP FOREIGN KEY(OBJECT_PATH) REFERENCES OBJECT_PROTECTION(OBJECT_PATH) ON DELETE CASCADE;
ALTER TABLE AUDIT_ENTRIES ADD CONSTRAINT FK_AE_PRINCIPALS FOREIGN KEY(PRINCIPAL_NAME) REFERENCES PRINCIPALS(PRINCIPAL_NAME);
ALTER TABLE STATION_ENDPOINTS ADD CONSTRAINT FK_SE_STATIONS FOREIGN KEY(STATION_NAME) REFERENCES STATIONS(STATION_NAME) ON DELETE CASCADE;
