ALTER TABLE SHIPMENT_PROPS ADD CONSTRAINT FK_SP_SHIPMENTS FOREIGN KEY(STATION_NAME, SHIPMENT_REF) REFERENCES SHIPMENTS(STATION_NAME, SHIPMENT_REF) ON DELETE CASCADE;
ALTER TABLE SHIPMENT_STATES ADD CONSTRAINT FK_SS_SHIPMENTS FOREIGN KEY(STATION_NAME, SHIPMENT_REF) REFERENCES SHIPMENTS(STATION_NAME, SHIPMENT_REF);
ALTER TABLE SHIPMENTS ADD CONSTRAINT FK_S_TARIFFS FOREIGN KEY(TARIFF_CODE) REFERENCES TARIFFS(TARIFF_CODE);
ALTER TABLE TARIFF_RULES ADD CONSTRAINT FK_TR_TARIFFS FOREIGN KEY(TARIFF_CODE) REFERENCES TARIFFS(TARIFF_CODE);
ALTER TABLE CREW_MEMBERS ADD CONSTRAINT FK_CRM_CREWS FOREIGN KEY(CREW_NAME) REFERENCES CREWS(CREW_NAME);
