ALTER TABLE ROUTE_HOPS ADD CONSTRAINT FK_RH_SEGMENTS FOREIGN KEY(SEGMENT_ID) REFERENCES ROUTE_SEGMENTS(SEGMENT_ID) ON DELETE CASCADE;
