ALTER TABLE SCHEDULES ADD CONSTRAINT FK_SCH_PLANS FOREIGN KEY(PLAN_NAME) REFERENCES ROUTE_PLANS(PLAN_NAME);
ALTER TABLE SCHEDULE_WINDOWS ADD CONSTRAINT FK_SW_SCHEDULES FOREIGN KEY(SCHEDULE_NAME) REFERENCES SCHEDULES(SCHEDULE_NAME) ON DELETE CASCADE;
