ALTER TABLE METRICS ADD CONSTRAINT FK_M_STATIONS FOREIGN KEY(STATION_NAME) REFERENCES STATIONS(STATION_NAME);
ALTER TABLE METRIC_SAMPLES ADD CONSTRAINT FK_MS_METRICS FOREIGN KEY(METRIC_NAME) REFERENCES METRICS(METRIC_NAME) ON DELETE CASCADE;
